```

---

### 场景 4: 自定义工具集成

```typescript
// 定义数据库查询工具
const queryDBTool = defineTool({
  name: 'query_database',
  description: 'Query the application database.',
  inputSchema: z.object({
    table: z.string(),
    filters: z.record(z.string(), z.any()).optional()
  }),
  execute: async ({ table, filters }) => {
    const results = await db.query(table, filters);
    return { results };
  }
});

// 注册到编排器
orchestrator.registerTool(queryDBTool);

// 在代理中使用
const agent = {
  name: 'data-analyst',
  model: 'gpt-4o',
  tools: ['query_database', 'fetch_data']
};
```

---

## 🌟 高级特性和模式

### 1. **循环检测（Loop Detection）**

```typescript
import { LoopDetector } from '@open-multi-agent/core';

const detector = new LoopDetector({
  maxLoops: 10,              // 最大循环次数
  similarityThreshold: 0.85  // 输出相似度阈值
});

// 在执行期间自动检测
if (detector.detectLoop(currentState, historyStates)) {
  throw new Error('Infinite loop detected!');
}
```

---

### 2. **代理池（AgentPool）- 资源管理**

```typescript
import { AgentPool, Semaphore } from '@open-multi-agent/core';

// 创建代理池（限制并发）
const pool = new AgentPool({
  maxConcurrent: 5,  // 最多 5 个代理同时运行
  timeout: 60000      // 超时时间
});

// 使用信号量进行资源控制
const semaphore = new Semaphore(3);  // 最多 3 个并发任务

await semaphore.acquire();
try {
  // 执行任务
} finally {
  semaphore.release();
}
```

---

### 3. **消息总线（MessageBus）- 代理间通信**

```typescript
import { MessageBus } from '@open-multi-agent/core';

const bus = new MessageBus();

// 代理发布消息
bus.publish({
  from: 'agent-a',
  to: 'agent-b',
  type: 'task_result',
  payload: { result: '...' }
});

// 代理订阅消息
bus.subscribe('agent-b', (message) => {
  console.log(`Received from ${message.from}:`, message.payload);
});
```

---

### 4. **结构化输出（Structured Output）**

```typescript
import { buildStructuredOutputInstruction, validateOutput } from '@open-multi-agent/core';
import { z } from 'zod';

// 定义输出模式
const outputSchema = z.object({
  title: z.string(),
  sections: z.array(z.object({
    heading: z.string(),
    content: z.string()
  })),
  conclusion: z.string()
});

// 在代理中使用
const agent = {
  name: 'writer',
  model: 'claude-opus-4-6',
  structuredOutput: outputSchema  // 强制结构化输出
};

const result = await orchestrator.runAgent(agent, 'Write a guide...');
// result.output 自动验证并解析为 TypeScript 类型
```

---

