                    <TableCell>排放源</TableCell>
                    <TableCell align="right">排放量 (吨)</TableCell>
                    <TableCell align="right">记录数</TableCell>
                    <TableCell align="right">占比</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {topActivities.map((activity, index) => (
                    <TableRow key={activity.type}>
                      <TableCell>{activity.type}</TableCell>
                      <TableCell align="right">{activity.total}</TableCell>
                      <TableCell align="right">{activity.count}</TableCell>
                      <TableCell align="right">
                        {((activity.total / totalEmission) * 100).toFixed(1)}%
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>

      {/* Recent Activities */}
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>
          最近录入记录
        </Typography>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>日期</TableCell>
                <TableCell>排放源</TableCell>
                <TableCell>活动量</TableCell>
                <TableCell>排放量 (kg)</TableCell>
                <TableCell>部门</TableCell>
                <TableCell>状态</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {yearlyData.slice(0, 10).map((record) => (
                <TableRow key={record.id}>
                  <TableCell>{record.date}</TableCell>
                  <TableCell>{record.activityType}</TableCell>
                  <TableCell>{record.activityAmount} {record.unit}</TableCell>
                  <TableCell>{record.emissionAmount.toFixed(2)}</TableCell>
                  <TableCell>{record.department}</TableCell>
                  <TableCell>
                    <Box
                      sx={{
                        bgcolor: 'success.light',
                        color: 'success.contrastText',
                        px: 1,
                        py: 0.5,
                        borderRadius: 1,
                        display: 'inline-block',
                      }}
                    >
                      已验证
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>
    </Container>
  );
}

export default Dashboard;
"}]

[{"type":"text","text":"import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    // Check for stored auth
    const storedUser = localStorage.getItem('carbonTrackUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
      setIsAuthenticated(true);
    }
  }, []);

  const login = (username, password) => {
    // Mock authentication - in production, this would call an API
    if (username && password) {
      const userData = {
        id: 1,
        username,
        name: username === 'admin' ? '系统管理员' : '普通用户',
        role: username === 'admin' ? 'admin' : 'user',
        permissions: username === 'admin' 
          ? ['all'] 
          : ['view', 'edit_own'],
      };
      setUser(userData);
      setIsAuthenticated(true);
      localStorage.setItem('carbonTrackUser', JSON.stringify(userData));
      return { success: true };
    }
    return { success: false, message: '用户名或密码错误' };
  };

  const logout = () => {
    setUser(null);
    setIsAuthenticated(false);
    localStorage.removeItem('carbonTrackUser');
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}
"}]

